import { MakeLogicType, afterMount, connect, kea, key, path, props } from 'kea'
import { subscriptions } from '../../utils/keaSubscriptions'
import { chatLogic } from '../frame/panels/Chat/chatLogic'
import { frameEditorsLogic } from '../frame/frameEditorsLogic'
import { workspaceLogic } from './workspaceLogic'
import type { FrameId } from '../../types'

export interface WorkspaceChatDrawerLogicProps {
  /** null for the frames home's chat, about no frame in particular. */
  frameId: FrameId | null
  nodeId?: string | null
  sceneId?: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workspaceChatDrawerLogicValues {
  linkableChatId: string | null // chatLogic
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workspaceChatDrawerLogicMeta {
  key: string
}

export type workspaceChatDrawerLogicType = MakeLogicType<
  workspaceChatDrawerLogicValues,
  {},
  WorkspaceChatDrawerLogicProps
> &
  workspaceChatDrawerLogicMeta

export const workspaceChatDrawerLogic = kea<workspaceChatDrawerLogicType>([
  path(['src', 'scenes', 'workspace', 'workspaceChatDrawerLogic']),
  props({} as WorkspaceChatDrawerLogicProps),
  key((props) => `${props.frameId ?? 'home'}:${props.sceneId ?? 'frame'}:${props.nodeId ?? 'scene'}`),
  connect((props: WorkspaceChatDrawerLogicProps) => ({
    values: [chatLogic({ frameId: props.frameId, sceneId: props.sceneId ?? null }), ['linkableChatId']],
  })),
  afterMount(({ props }) => {
    const chat = chatLogic({ frameId: props.frameId, sceneId: props.sceneId ?? null })
    // The URL names the chat (a reload, the Back button).
    const urlChatId = workspaceLogic.values.chatDrawerSelection?.chatId

    // An AI box question (workspaceLogic.startAiChat) is already on its way
    // in a chat of its own: keep showing that one.
    if (!urlChatId && chat.values.isSubmitting && chat.values.activeChatId) {
      return
    }

    if (props.frameId !== null && props.sceneId) {
      frameEditorsLogic({ frameId: props.frameId }).actions.selectScene(props.sceneId)
    }
    if (urlChatId) {
      chat.actions.openChat(urlChatId)
    } else if (props.frameId === null) {
      chat.actions.ensureFrameChat()
    } else if (props.sceneId && props.nodeId) {
      chat.actions.ensureChatForApp(props.sceneId, props.nodeId)
    } else if (props.sceneId) {
      chat.actions.ensureChatForScene(props.sceneId)
    } else {
      chat.actions.ensureFrameChat()
    }
  }),
  // After afterMount, so the first value is the chat the URL named.
  subscriptions(() => ({
    linkableChatId: (chatId: string | null) => {
      if ((workspaceLogic.values.chatDrawerSelection?.chatId ?? null) !== chatId) {
        workspaceLogic.actions.setChatDrawerChatId(chatId)
      }
    },
  })),
])
